import auditQueries from "@tepian-k3/queries/platform/audit.queries";
import settingQueries from "@tepian-k3/queries/platform/setting.queries";
import settingSchema from "@tepian-k3/schema/platform/setting.schema";
import { Effect } from "effect";
import { z } from "zod";
import {
  createTRPCRouter,
  formDataInput,
  formDataProcedure,
  publicProcedure,
  withPermission,
} from "../..";
import { processAndUploadImage } from "../../utils/image-upload";
import { runEffect } from "../../utils/run-effect";

export const settingRouter = createTRPCRouter({
  // 1. Get Setting by Key (Public query)
  getByKey: publicProcedure
    .input(settingSchema.getSettingByKeySchema)
    .query(async ({ input }) => {
      return await runEffect(
        Effect.gen(function* () {
          const setting = yield* settingQueries.getSettingByKey(input.key);

          return setting ? setting : null;
        }),
      );
    }),

  // 2. Set/Upsert Setting (Admin only, with audit logs)
  set: withPermission("banners.create")
    .input(settingSchema.setSettingSchema)
    .mutation(async ({ input, ctx }) => {
      return await runEffect(
        Effect.gen(function* () {
          const oldRecord = yield* settingQueries.getSettingByKey(input.key);
          const result = yield* settingQueries.setSetting(input);

          // Create audit log
          yield* auditQueries.createAuditLog({
            entityType: "setting",
            entityId: result.id,
            action: oldRecord ? "update" : "create",
            userId: ctx.user.id,
            userEmail: ctx.user.email,
            oldValues: oldRecord || null,
            newValues: result,
            description: `Mengonfigurasi setting "${input.key}" menjadi: "${input.value}"`,
          });

          return result;
        }),
      );
    }),

  // 3. Upload Setting Image (Admin only, handles multipart/form-data upload)
  uploadSettingImage: withPermission("banners.create")
    .input(formDataInput)
    .use(
      formDataProcedure(
        z.object({
          picture: z
            .file()
            .max(5 * 1024 * 1024)
            .mime(["image/jpeg", "image/png", "image/webp"]),
        }),
      ),
    )
    .mutation(async ({ ctx }) => {
      return await runEffect(
        Effect.gen(function* () {
          const uploadedFile = yield* processAndUploadImage(
            ctx.input.data.picture,
            { folder: "settings" },
          );
          return { key: uploadedFile.key };
        }),
      );
    }),
});

